import java.util.*;

public class GenericMethods {
    // Generic method
    public static <T> void printArray(T[] array) {
        for (T element : array) {
            System.out.println(element);
        }
    }

    // Bounded type parameter
    public static <T extends Comparable<T>> T findMax(T[] array) {
        T max = array[0];
        for (T element : array) {
            if (element.compareTo(max) > 0) {
                max = element;
            }
        }
        return max;
    }

    // Multiple bounds
    public static <T extends Number & Comparable<T>> T findMaxNumber(List<T> list) {
        T max = list.get(0);
        for (T num : list) {
            if (num.compareTo(max) > 0) {
                max = num;
            }
        }
        return max;
    }

    public static void main(String[] args) {
        Integer[] numbers = {3, 1, 4, 1, 5, 9};
        System.out.println("Max: " + findMax(numbers));

        String[] words = {"cherry", "apple", "banana"};
        System.out.println("Max: " + findMax(words));

        List<Double> doubles = Arrays.asList(3.14, 2.71, 1.41);
        System.out.println("Max double: " + findMaxNumber(doubles));
    }
}

import java.util.*;

public class WildcardDemo {
    // Unbounded wildcard: any type
    public static void printList(List<?> list) {
        for (Object elem : list) {
            System.out.println(elem);
        }
    }

    // Upper bounded: Number or its subclasses
    public static double sumOfList(List<? extends Number> list) {
        double sum = 0;
        for (Number num : list) {
            sum += num.doubleValue();
        }
        return sum;
    }

    // Lower bounded: Integer or its superclasses
    public static void addNumbers(List<? super Integer> list) {
        list.add(1);
        list.add(2);
        list.add(3);
    }

    public static void main(String[] args) {
        List<Integer> ints = Arrays.asList(1, 2, 3);
        List<Double> doubles = Arrays.asList(1.5, 2.5, 3.5);

        System.out.println("Sum of ints: " + sumOfList(ints));
        System.out.println("Sum of doubles: " + sumOfList(doubles));

        List<Number> numbers = new ArrayList<>();
        addNumbers(numbers);
        System.out.println("Numbers: " + numbers);
    }
}

